class.description:
It is the first argument, before the arguments of [method NetwAction.request]. Call [method bind] on a node the action spawns, before adding it to the tree. Call [method deny] to reject the action.
[codeblock]
func _place_bomb(ctx: NetwActionContext) -> void:
    var past := Netw.sample(entity, ctx.view_tick)
    if not past.has_value(&"position"):
        ctx.deny()
        return
    var bomb := BOMB.instantiate()
    ctx.bind(bomb)
    bombs.add_child(bomb)
[/codeblock]
